import type { LessonContent, LessonQuestion } from '../content-types';

type Exercise = Omit<LessonQuestion, 'id'>;
const choice = (prompt: string, choices: string[], answer: string, explanation: string, difficulty: 1|2|3|4 = 1): Exercise => {
 const offset = [...prompt].reduce((sum, letter) => sum + letter.codePointAt(0)!, 0) % choices.length;
 return {kind:'choice',prompt,choices:[...choices.slice(offset),...choices.slice(0,offset)],answer,explanation,difficulty,hints:['Hem öğrenme amacını hem herkesin güvenle katılmasını düşün.']};
};
const truth = (prompt: string, correct: boolean, explanation: string, difficulty: 1|2|3|4 = 2): Exercise => ({kind:'boolean',prompt,choices:['Doğru','Yanlış'],answer:correct?'Doğru':'Yanlış',explanation,difficulty,hints:['İfadede herkes için geçerli olmayan bir genelleme olup olmadığını incele.']});
const section = (title: string, ...body: string[]) => ({title,body});
const safety = 'Hareket içeren seçenekleri yalnız öğretmenin veya sorumlu bir yetişkinin uygun bulduğu güvenli ortamda ve kendi rahat hareket sınırın içinde yap. Ağrı, baş dönmesi veya rahatsızlık hissedersen durup yetişkine haber ver. Oturarak, çizerek veya gözlemci olarak katılabilirsin.';
function lesson(topicId:string,introduction:string,sections:LessonContent['sections'],workedExample:LessonContent['workedExample'],exercises:Exercise[],activity:NonNullable<LessonContent['activity']>):LessonContent {
 return {topicId,introduction,sections,workedExample,questions:exercises.map((q,i)=>({...q,id:`gs-${topicId}-${i+1}`})),activity:{...activity,instructions:[safety,...activity.instructions]}};
}

